import {worldPath} from './cyclone-map.js?v=20261023-ecosystems01';
const worldPoint=(lon,lat)=>({x:20+(lon+180)/360*400,y:65+(90-lat)/180*200});
import {UK_PATH} from './uk-outline.js?v=20261023-geography01';
export const ecoViews={
 'eco-biomes':[['tropical','Tropical forest'],['temperate','Temperate forest'],['boreal','Boreal forest'],['grass-tropical','Tropical grassland'],['grass-temperate','Temperate grassland'],['desert','Desert'],['tundra','Tundra']],
 'eco-controls':[['climate','Compare climates'],['soil','Soil & drainage'],['climb','Climb a mountain']],
 'eco-resources':[['supply','Food, medicine & wood'],['mine','Commercial extraction'],['water','Water abstraction'],['balance','Harvest & renewal']],
 'eco-uk-land':[['moor','Moorland'],['heath','Heathland'],['woodland','Woodland'],['wetland','Wetlands']],
 'eco-uk-marine':[['nursery','Marine habitats'],['nutrients','Nutrients & light'],['abrasion','Seabed disturbance'],['protect','Reduce pressures']]
};
export const ecoRequirements=Object.fromEntries(Object.entries(ecoViews).map(([k,v])=>[k,v.map(x=>x[0])]));
export const ecoAnimated=(k,v)=>k==='eco-controls'?v==='climb':k==='eco-resources'?true:k==='eco-uk-marine'?v!=='nursery':false;
const text=(x,y,s,size=13)=>`<text x="${x}" y="${y}" font-size="${size}">${s}</text>`;
const line=(d,c='#b6d5de',w=3)=>`<path d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round"/>`;
const dot=(x,y,r=6,c='#efb49f')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`;
const box=(x,y,w,s)=>`<rect x="${x}" y="${y}" width="${w}" height="48" rx="10" fill="#38576c" stroke="#9db8c1"/>`+text(x+12,y+29,s,12);
const svg=(body,caption)=>`<svg class="geo-scene" viewBox="0 0 440 350" role="img" aria-label="${caption.replaceAll('&','&amp;').replaceAll('"','&quot;')}"><g fill="#eef2f2" font-family="sans-serif">${body}</g></svg>`;
const wrap=(body,caption)=>svg(body,caption)+`<p class="geo-caption">${caption}</p>`;
const link=(url,s)=>`<a href="${url}" target="_blank" rel="noopener">${s}</a>`;
export const climateExamples=[
 {name:'Manaus, Brazil',rain:[288,289,308,310,245,122,92,68,88,122,174,217],temp:[27,27,27,27,27,27,27,28,28,28,28,27],url:'https://science.nasa.gov/kids/earth/mission-biomes/biorainforest/'},
 {name:'Aklavik, Canada',rain:[15,12,14,8,15,19,40,42,30,33,22,16],temp:[-27,-26,-22,-12,0,10,14,11,4,-7,-20,-25],url:'https://science.nasa.gov/kids/earth/mission-biomes/biotundra/'}
];
export const climateRange=x=>Math.max(...x.temp)-Math.min(...x.temp);
const values=()=>`<table class="geo-data"><caption>NASA Mission: Biomes · published monthly summaries · 1970–2000</caption><thead><tr><th scope="col">Month</th><th scope="col">Manaus mm / °C</th><th scope="col">Aklavik mm / °C</th></tr></thead><tbody>${'Jan Feb Mar Apr May Jun Jul Aug Sep Oct Nov Dec'.split(' ').map((m,i)=>`<tr><th scope="row">${m}</th>${climateExamples.map(s=>`<td>${s.rain[i]} / ${s.temp[i]}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
export function ecoEvidence(){let body=text(20,25,'TWO LOCATIONS · MATCHING AXIS SCALES',14);for(let j=0;j<2;j++){const d=climateExamples[j],x0=45+j*210,Y=v=>270-(v+30)/70*180,X=i=>x0+i*13;body+=text(x0-15,56,d.name,12);for(const v of[0,200,400]){const y=270-v/400*180;body+=line(`M${x0} ${y}h150`,'#718fa1',1)+text(x0-27,y+4,''+v,9);}body+=text(x0-23,77,'mm',10)+text(x0+153,77,'°C',10);for(const v of[-30,0,40])body+=text(x0+153,Y(v)+4,''+v,9);d.rain.forEach((v,i)=>{body+=`<rect x="${X(i)}" y="${270-v/400*180}" width="9" height="${v/400*180}" fill="#9ec9d6"/>`+text(X(i),286,'JFMAMJJASOND'[i],9);});body+=line(d.temp.map((v,i)=>(i?'L':'M')+(X(i)+4)+' '+Y(v)).join(' '),'#f6ae97',2);d.temp.forEach((v,i)=>body+=dot(X(i)+4,Y(v),2,'#f6ae97'));}body+=text(20,317,'Bars: precipitation (mm) · line: temperature (°C)',12)+text(20,339,'Monthly means · 1970–2000 · not daily extremes',11);return svg(body,'Two climate graphs on matching precipitation0–400mm and temperature−30–40°C axes. Manaus and Aklavik, published1970–2000 monthly summaries.')+`<p class="geo-caption">${climateExamples.map(s=>link(s.url,'NASA: '+s.name)).join(' · ')}. Published monthly means1970–2000; rounded values,not current weather. ${link('./geography/data/biome-climate-source.json','Archived source values')}. Each right axis is temperature; each left axis is precipitation.</p><details class="geo-chart-values"><summary>Read chart values</summary>${values()}</details>`;}
const biomeData={
 tropical:['TROPICAL FOREST','Warm; wet rainforest / seasonal dry forest','Dense layered vegetation in wet regions',[[ -60,-4],[24,0],[110,0]],'Amazonia · Congo Basin · Southeast Asia'],
 temperate:['TEMPERATE FOREST','Moderate rain; marked temperature seasons','Broadleaf / mixed forests; seasonal leaf loss',[[-80,40],[12,48],[125,35]],'Eastern N America · Europe · East Asia'],
 boreal:['BOREAL FOREST','Long cold winters; short growing season','Mainly conifers across northern continents',[[-110,58],[25,63],[100,60]],'Canada · Scandinavia · Russia'],
 'grass-tropical':['TROPICAL GRASSLAND','Warm; distinct wet and dry seasons','Grasses with scattered trees',[[35,-3],[-48,-15],[133,-16]],'East Africa · Brazil · northern Australia'],
 'grass-temperate':['TEMPERATE GRASSLAND','Warm summers / cold winters; limited rain','Grasses; few trees; extensive root systems',[[-103,43],[-62,-35],[70,48]],'Prairies · pampas · Eurasian steppes'],
 desert:['DESERT','Very low precipitation; hot or cold','Sparse vegetation adapted to water shortage',[[10,24],[45,24],[135,-25],[95,42]],'Sahara · Arabia · Australia · interior Asia'],
 tundra:['TUNDRA','Very cold winters; brief growing season','Low shrubs, mosses, lichens; often permafrost',[[-130,69],[75,70],[125,70]],'Arctic margins · alpine examples elsewhere']
};
// Labelled approximate centres locate broad regions, not mapped biome boundaries.
export function ecoScene(k,selection,t=0){if(!ecoViews[k])return '';const v=ecoRequirements[k].includes(selection)?selection:ecoRequirements[k][0];t=ecoAnimated(k,v)?Math.max(0,Math.min(1,Number(t)||0)):0;let b='',c='';
if(k==='eco-biomes'){const d=biomeData[v];b=text(20,28,d[0],17)+`<path d="${worldPath}" fill="#688c98" stroke="#b4cbd0" stroke-width=".5"/>`+line('M20 165H420','#edc0a6',1)+text(24,161,'Equator',10);d[3].forEach(([lon,lat],i)=>{const p=worldPoint(lon,lat);b+=dot(p.x,p.y,12,'#efb49f')+text(p.x-3,p.y+4,''+(i+1),11);});b+=text(20,290,d[1],12)+text(20,313,d[2],12)+text(20,338,d[4],11);c='Selected representative regions, not measured biome boundaries or a complete extent map. Natural Earth public-domain basemap. '+d[4]+'. Climate, soils, altitude and human use produce transitions and local variation; tundra also occurs on high mountains. Sources: NASA Mission: Biomes; University of Michigan Animal Diversity Web.';}
if(k==='eco-controls'){
 if(v==='climate')return ecoEvidence();
 if(v==='soil'){b=text(20,30,'ONE REGIONAL CLIMATE · DIFFERENT SOILS',14)+`<path d="M25 165Q120 140 210 185T415 165V300H25Z" fill="#a18e7a"/><ellipse cx="220" cy="205" rx="67" ry="20" fill="#79adbf"/>`+text(35,100,'Acidic, nutrient-poor',12)+text(35,125,'Heath plants',12)+text(255,100,'Water at surface',12)+text(255,125,'Wetland plants',12)+line('M80 160v-20m0 8l-12-7m12 2l12-9','#b7c7ae',4)+line('M230 200v-35m0 13l-10-9m10 3l10-10','#bdd5ab',4)+text(25,330,'Drainage, nutrients and rooting conditions differ',12);c='Schematic local comparison, not a measured soil transect. Climate does not remove local differences in drainage, acidity, nutrients and soil depth. Soil formation also depends on climate, organisms, parent material and time. Heath and wetland are examples, not universal fixed outcomes.';}
 else{const y=285-200*t;b=text(20,30,'ALTITUDE MODIFIES THE GROWING SEASON',14)+`<path d="M45 300L230 65 415 300Z" fill="#7f939a"/><path d="M185 124L230 65 275 124Z" fill="#d8e1de"/>`+line('M110 260v-40m-18 20h36','#b5c9ab',7)+line('M145 210v-25m-10 12h20','#b5c9ab',5)+line('M180 166h15','#b5c9ab',5)+dot(55+175*t,y,8)+text(25,325,'Generally cooler, more exposed → shorter growth',12);c='Follow a conceptual climb from woodland towards low alpine vegetation. The moving marker shows increasing elevation, not a plant moving uphill or a measured vegetation-change timescale. No universal treeline height is implied; regional climate, exposure, soils and snow duration vary.';}
}
if(k==='eco-resources'){
 if(v==='supply'){b=text(20,30,'LIVING SYSTEMS → USEFUL RESOURCES',14)+box(90,65,260,'Plants, animals and other organisms')+box(25,190,180,'Food / tested medicines')+box(235,190,180,'Building timber / fuelwood')+line('M160 120L110 185')+line('M280 120L325 185')+dot(160-50*t,120+65*t)+dot(280+45*t,120+65*t)+text(25,315,'Human benefits depend on continuing ecosystem function',11);c='Symbolic resource pathways: food, biologically derived medicine compounds, timber and biomass fuel. Dots represent provision, not equal quantities or literal movement of every product. Wild plants are not automatically safe treatments; medicines require testing.';}
 else if(v==='mine'){b=text(20,30,'COMMERCIAL EXTRACTION → HABITAT PRESSURE',13)+`<path d="M25 240H415V300H25Z" fill="#a18e7a"/><path d="M180 240L220 290 300 290 340 240Z" fill="#526c7b"/>`+box(25,75,180,'Energy / mineral demand')+box(235,75,180,'Roads / clearance / waste')+line('M120 130L280 225')+dot(120+160*t,130+95*t)+text(25,330,'Geological resources; impacts on living ecosystems',12);c='A causal pathway from commercial extraction to disturbance. This is not a measured mine or an assertion that all schemes have equal impacts. Mineral ores have geological origins; habitat clearance, fragmentation and waste can affect the biosphere.';}
 else if(v==='water'){b=text(20,30,'ABSTRACTION LINKS SUPPLY AND HABITATS',14)+`<ellipse cx="115" cy="240" rx="80" ry="${45-20*t}" fill="#78a8ba"/>`+box(245,100,170,'Human water supply')+line('M145 215L300 155')+dot(145+155*t,215-60*t)+text(25,315,'Removal can reduce water available to organisms',12);c='Conceptual abstraction from an ecosystem supporting people and wildlife. The shrinking water shape is invented, not a recorded UK wetland time series. Outcomes depend on replenishment, demand, management and ecological water requirements.';}
 else{b=text(20,30,'COMPARE HARVEST WITH RENEWAL',14);for(let i=0;i<2;i++){const x=45+i*205,h=110-(i?65:0)*t;b+=text(x,80,i?'Harvest exceeds regrowth':'Managed regrowth',12)+`<rect x="${x}" y="${270-h}" width="130" height="${h}" rx="8" fill="${i?'#efb49f':'#a9c5b5'}"/>`+text(x,300,i?'Stock declines':'Stock maintained',12);}c='Invented equal-start biomass stocks: one harvest is matched by regrowth, the other exceeds it. Bars represent only a simplified biomass balance, not a guarantee of biodiversity or a real forest forecast. Mineral deposits do not renew this way on human timescales; loops reset the comparison.';}
}
if(k==='eco-uk-land'){
 const data={moor:['MOORLAND','Cool, exposed uplands','Heather, grasses, peat / bog mosaics',[[107,76],[167,166],[132,255]],'Scotland · Pennines · Dartmoor'],heath:['LOWLAND HEATH','Often acidic, nutrient-poor soils','Heather, gorse and open ground',[[171.4,249.6],[185.2,248.2],[208.2,238.4]],'Dorset / New Forest · Surrey'],woodland:['WOODLAND','Broadleaf / conifer communities','Occurs across the UK; management matters',[[117,100],[157,207],[195,235]],'Selected examples across the UK'],wetland:['WETLAND','Water near / at the surface','Bogs, fens, marshes and floodplains',[[256.5,196.4],[155.3,241.2],[130,48]],'Broads · Somerset · Scottish peatlands']}[v];
 b=text(20,30,data[0],17)+`<path d="${UK_PATH}" fill="#7896a5" stroke="#c0d0d4" stroke-width="1.1"/>`+text(255,110,'N ↑',15)+text(255,170,'Example sites',12);data[3].forEach(([x,y],i)=>b+=dot(x,y,8)+text(x-3,y+4,''+(i+1),10));b+=text(20,300,data[1],12)+text(20,324,data[2],12);c=data[4]+'. Representative locators, not habitat boundaries, complete UK extent, a current inventory or GIS analysis. Categories can overlap, especially moorland and wetland. Natural Earth public-domain outline; habitat context from JNCC and Woodland Trust.';
}
if(k==='eco-uk-marine'){
 b=text(20,30,{nursery:'MARINE HABITATS SUPPORT RESOURCES',nutrients:'NUTRIENTS → ALGAE → LESS LIGHT',abrasion:'PHYSICAL CONTACT → HABITAT DAMAGE',protect:'REDUCE PRESSURES BEFORE RESTORATION'}[v],14)+`<rect x="25" y="65" width="390" height="225" rx="12" fill="#426b80"/><path d="M25 275Q180 250 415 280V300H25Z" fill="#a79b88"/>`;
 if(v==='nursery'){for(let i=0;i<7;i++)b+=line(`M${60+i*18} 275q-12-38 3-70`,'#bfd2b0',5);for(let i=0;i<4;i++)b+=line(`M${315+i*20} 270q-30-90 0-145`,'#96bdab',10);b+=text(40,100,'Seagrass: flowering plant',12)+text(265,100,'Kelp: alga',12)+text(35,330,'Food · nursery habitat · livelihoods · recreation',12);c='Schematic UK coastal habitats, not a species-identification photograph or actual seabed survey. Seagrass grows rooted in shallow sediments with enough light; kelp attaches to suitable rocky surfaces. Nursery functions support some species, not all marine organisms.';}
 else if(v==='nutrients'){b+=`<rect x="25" y="80" width="390" height="${15+40*t}" fill="#a2b17a" opacity=".7"/>`;for(let i=0;i<6;i++){b+=line(`M${90+i*45} 130v${100-65*t}`,'#efd9a8',3)+line(`M${90+i*45} 270q-10-25 0-55`,'#b9d2ac',4);}b+=text(40,195,'Algal growth can reduce underwater light',12)+text(25,330,'A mechanism, not a measured bloom timeline',12);c='Excess nutrients can encourage algae and reduce light reaching seagrass. Rays shorten as available light decreases; these lengths are symbolic, not measured light intensity or exact nutrient concentrations. Sources: MMO seagrass guidance; JNCC pressures.';}
 else if(v==='abrasion'){const x=65+300*t;b+=`<path d="M${x} 115v120m-18-20q18 36 36 0" fill="none" stroke="#eab39f" stroke-width="5"/><rect x="55" y="255" width="${30+300*t}" height="22" fill="#b7aa94"/>`;for(let i=0;i<8;i++)if(70+i*40>x)b+=line(`M${70+i*40} 270q-12-30 0-55`,'#b8cba7',5);b+=text(25,330,'Dragging anchors can uproot / fragment seagrass',12);c='Conceptual anchor dragged across a seagrass bed, leaving a disturbance track. Not a real boat route or damage-rate measurement. Bottom-contact fishing gear can also abrade sensitive seabeds; activity, habitat and exposure determine effects.';}
 else{b+=box(45,90,350,'Manage anchoring / fishing / water quality')+box(70,215,300,'Habitat monitoring + suitable restoration')+line('M220 145V205')+dot(220,145+60*t)+text(25,330,'Designation alone does not demonstrate recovery',12);c='Reducing damaging pressures can support recovery, but outcomes require monitoring and may be slow or uncertain. The moving link is a management sequence, not a predicted UK recovery movie. A protected-area name does not establish which activities are restricted.';}
}
return wrap(b,c);
}
